/** Connected private editor journey. No placement, renderer, motion or canonical-registration claim. */
@EventBusSubscriber(modid="vandorlabs")
public final class CanopyEditorWorldFixture {
 static final BlockPos[] ROOTS={new BlockPos(0,100,0),new BlockPos(10,100,0)};static final BlockPos ACK=new BlockPos(4,100,-5);
 static final Map<String,NativeCanopyBlock> BLOCKS=new LinkedHashMap<>();static BlockEntityType<NativeCanopyEntity> type;static MenuType<NativeCanopyMenu> menuType;
 static int step,checks;static UUID actor;static boolean clicked,sneaking,tool;static Vec3 target;
 static boolean enabled(){return Boolean.getBoolean("vandorlabs.canopyEditorWorldCheck");}
 static void need(boolean yes,String why){checks++;if(!yes)throw new AssertionError("Canopy editor world step="+step+": "+why);}
 static BlockPos root(int step){return ROOTS[step<4?0:1];}static GameType mode(int step){return step==0||step==4?GameType.CREATIVE:GameType.SURVIVAL;}
 static boolean sneak(int step){return step==0||step==2||step==3||step==4;}static ItemStack held(int step){return step==1||step==2||step==5?new ItemStack(VandorLabsBootstrap.CONFIGURIZER.get()):ItemStack.EMPTY;}
 public record Ack(int step) implements CustomPacketPayload {static final Type<Ack> TYPE=new Type<>(ResourceLocation.parse("vandorlabs:canopy_editor_world_ack"));public Type<? extends CustomPacketPayload> type(){return TYPE;}}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration {
  @SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent event){if(!enabled())return;
   event.register(Registries.BLOCK,h->{for(String kind:new String[]{"canopy","front_canopy_glass"}){var block=new NativeCanopyBlock(kind,()->type,()->menuType,net.minecraft.world.level.block.state.BlockBehaviour.Properties.of().strength(1.5F).sound(SoundType.GLASS));BLOCKS.put(kind,block);h.register(ResourceLocation.parse("vandorlabs:canopy_editor_world_"+kind),block);}});
   event.register(Registries.BLOCK_ENTITY_TYPE,h->{type=BlockEntityType.Builder.of((pos,state)->new NativeCanopyEntity(type,pos,state,((NativeCanopyBlock)state.getBlock()).kind()),BLOCKS.values().toArray(Block[]::new)).build(null);h.register(ResourceLocation.parse("vandorlabs:canopy_editor_world_fixture"),type);});
   event.register(Registries.MENU,h->{menuType=net.neoforged.neoforge.common.extensions.IMenuTypeExtension.create((id,inventory,b)->new NativeCanopyMenu(menuType,id,inventory,b.readBlockPos()));h.register(ResourceLocation.parse("vandorlabs:canopy_editor_world_fixture"),menuType);});
  }
  @SubscribeEvent public static void payload(net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent event){if(!enabled())return;CanopySettingsPayload.register(event);event.registrar("1").playToServer(Ack.TYPE,new StreamCodec<RegistryFriendlyByteBuf,Ack>(){public Ack decode(RegistryFriendlyByteBuf b){if(b.readableBytes()!=1)throw new IllegalArgumentException("Canopy fixture ack length");int step=b.readUnsignedByte();if(step>5)throw new IllegalArgumentException("Canopy fixture step");return new Ack(step);}public void encode(RegistryFriendlyByteBuf b,Ack value){b.writeByte(value.step);}},(packet,context)->context.enqueueWork(()->{if(context.player() instanceof ServerPlayer player)ack(player,packet.step);}));}
 }
 @SubscribeEvent public static void use(PlayerInteractEvent.RightClickBlock event){if(enabled()&&event.getEntity() instanceof ServerPlayer player&&player.getUUID().equals(actor)&&event.getHand()==InteractionHand.MAIN_HAND&&player.level().getBlockEntity(event.getPos()) instanceof NativeCanopyEntity){clicked=true;sneaking=player.isShiftKeyDown();tool=player.getMainHandItem().is(VandorLabsBootstrap.CONFIGURIZER.get());}}
 private static NativeCanopyEntity install(net.minecraft.server.level.ServerLevel level,BlockPos root,String kind){var block=BLOCKS.get(kind);var saved=new CompoundTag();saved.putLong("Anchor",com.vandorlabs.persistence.LegacyBlockPosition.pack(root.getX(),root.getY(),root.getZ()));saved.putString("PrivateCanopyEditor","server-only");level.setBlock(root,block.defaultBlockState().setValue(NativeCanopyBlock.FACING,Direction.NORTH),18);var owner=(NativeCanopyEntity)level.getBlockEntity(root);owner.loadWithComponents(saved,level.registryAccess());var cells=NativeCanopyFootprint.cells(kind,root,owner.facing(),owner.settings(),owner.links());owner.configurationFootprint(cells);for(var pos:cells)if(!pos.equals(root)){level.setBlock(pos,block.defaultBlockState().setValue(NativeCanopyBlock.FACING,Direction.NORTH),18);((NativeCanopyEntity)level.getBlockEntity(pos)).helperOf(owner);}NativeCanopyLifecycle.prepare(owner);return owner;}
 @SubscribeEvent public static void login(PlayerEvent.PlayerLoggedInEvent event){if(!enabled()||!(event.getEntity() instanceof ServerPlayer player))return;actor=player.getUUID();var level=player.serverLevel();level.getGameRules().getRule(GameRules.RULE_DAYLIGHT).set(false,player.getServer());level.getGameRules().getRule(GameRules.RULE_DOMOBSPAWNING).set(false,player.getServer());level.setDayTime(6000);for(int x=-5;x<=17;x++)for(int z=-6;z<=7;z++){level.setBlock(new BlockPos(x,99,z),Blocks.STONE.defaultBlockState(),3);for(int y=100;y<108;y++)level.setBlock(new BlockPos(x,y,z),Blocks.AIR.defaultBlockState(),3);}install(level,ROOTS[0],"canopy");var front=install(level,ROOTS[1],"front_canopy_glass");var next=new CompoundTag();front.settings().write(next);next.putInt("CanopyDepth",80);var cells=NativeCanopyFootprint.cells(front.kind(),ROOTS[1],front.facing(),front.settings(),front.links());var obstacle=NativeCanopyFootprint.shell(front.kind(),ROOTS[1],front.facing(),NativeCanopySettings.read(next),false).stream().filter(p->!cells.contains(p)).findFirst().orElseThrow();level.setBlock(obstacle,Blocks.STONE.defaultBlockState(),3);setup(player);System.out.println("[vandorlabs][canopy-editor-world] setup PASS");}
 static void setup(ServerPlayer player){clicked=false;var level=player.serverLevel();var pos=root(step);var owner=(NativeCanopyEntity)level.getBlockEntity(pos);NativeCanopyLifecycle.prepare(owner);var bounds=owner.publication().geometry().bounds();double x=pos.getX()+.5,y=100,z=pos.getZ()-3;var eye=new Vec3(x,y+player.getEyeHeight(),z);target=null;for(int yi=1;yi<=3&&target==null;yi++)for(int xi=1;xi<=3&&target==null;xi++){var end=new Vec3(bounds.minX+(bounds.maxX-bounds.minX)*xi/4,bounds.minY+(bounds.maxY-bounds.minY)*yi/4,bounds.maxZ+.2);var hit=owner.publication().geometry().trace(new com.vandorlabs.canopy.CanopyPoint(eye.x,eye.y,eye.z),new com.vandorlabs.canopy.CanopyPoint(end.x,end.y,end.z));if(hit!=null)target=new Vec3(hit.x,hit.y,hit.z);}need(target!=null,"authored front ray target");player.setGameMode(mode(step));player.getInventory().clearContent();player.getInventory().selected=0;player.setItemInHand(InteractionHand.MAIN_HAND,held(step));player.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);player.setShiftKeyDown(sneak(step));double dx=target.x-x,dy=target.y-y-player.getEyeHeight(),dz=target.z-z;player.connection.teleport(x,y,z,(float)-Math.toDegrees(Math.atan2(dx,dz)),(float)-Math.toDegrees(Math.atan2(dy,Math.sqrt(dx*dx+dz*dz))));player.connection.send(new net.minecraft.network.protocol.game.ClientboundSetCarriedItemPacket(0));player.inventoryMenu.broadcastChanges();level.setBlock(ACK,Blocks.NOTE_BLOCK.defaultBlockState().setValue(NoteBlock.NOTE,step),3);System.out.println("[vandorlabs][canopy-editor-world] ready step="+step+" mode="+mode(step)+" held="+held(step)+" target="+target);}
 static void ack(ServerPlayer player,int received){need(player.getUUID().equals(actor)&&received==step&&player.gameMode.getGameModeForPlayer()==mode(step),"current actor/mode/step");need(clicked&&sneaking==sneak(step)&&tool==!held(step).isEmpty(),"actual packet use-time held/sneak");need(player.containerMenu==player.inventoryMenu,"real menu closed");var owner=(NativeCanopyEntity)player.level().getBlockEntity(root(step));if(step<3)need(owner.settings().data().tint==(step+2)%4,"actual button edit reached authority");if(step==4)need(owner.settings().data().depth==16,"blocked resize retains depth");if(step==5)need(owner.settings().data().tint==2&&owner.settings().data().shade==0,"valid edit and stale-window refusal");need(owner.saveWithoutMetadata(player.registryAccess()).getString("PrivateCanopyEditor").equals("server-only")&&!owner.getUpdateTag(player.registryAccess()).toString().contains("server-only"),"private data preserved/excluded");if(++step<6)setup(player);else{player.level().setBlock(ACK,Blocks.NOTE_BLOCK.defaultBlockState().setValue(NoteBlock.NOTE,6),3);System.out.println("[vandorlabs][canopy-editor-world] server PASS checks="+checks);}}
 @SubscribeEvent public static void logout(PlayerEvent.PlayerLoggedOutEvent event){if(enabled()&&event.getEntity().getUUID().equals(actor)){need(step==6,"all editor player stages");System.out.println("[vandorlabs][canopy-editor-world] logout PASS");}}
}
